**`main.js`**
```javascript
const { app, BrowserWindow, ipcMain, Notification } = require('electron');
const path = require('path');

let mainWindow;
let timerId = null;

function createWindow () {
  mainWindow = new BrowserWindow({
    width: 400,
    height: 300,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true
    }
  });

  mainWindow.loadFile('index.html');
}

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

ipcMain.handle('start-timer', () => {
  if (timerId) clearTimeout(timerId);

  timerId = setTimeout(() => {
    new Notification({
      title: 'Work Reminder',
      body: 'You’ve been working for 30 minutes. Take a break!'
    }).show();

    if (mainWindow) {
      mainWindow.webContents.send('timer-done');
    }

    timerId = null;
  }, 30 * 60 * 1000);

  return Date.now() + 30 * 60 * 1000;
});

ipcMain.handle('cancel-timer', () => {
  if (timerId) {
    clearTimeout(timerId);
    timerId = null;
  }
});
```

**`preload.js`**
```javascript
const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('electronAPI', {
  startTimer: () => ipcRenderer.invoke('start-timer'),
  cancelTimer: () => ipcRenderer.invoke('cancel-timer'),
  onTimerDone: (callback) => ipcRenderer.on('timer-done', callback)
});
```

